interface ILogItem {
    timestamp: number;
    message: string;
}
interface IMessage<Payload = unknown> {
    id?: string | number;
    payload: Payload;
    clientMsgId: string;
}
interface IMessageMeta {
    prefix?: string;
    prefixColor?: string;
    messageName?: string;
}
interface ILogger<Message extends IMessage> {
    enable: () => void;
    disable: () => void;
    getLogs: () => ILogItem[];
    info: (text: string, ...causes: unknown[]) => void;
    error: (text: string, ...causes: unknown[]) => void;
    warn: (text: string, ...causes: unknown[]) => void;
    request: (item: Message, meta?: IMessageMeta) => void;
    response: (item: Message, meta?: IMessageMeta) => void;
    event: (item: Message, meta?: IMessageMeta) => void;
}
declare const createLogger: <Message extends IMessage>(isEnabled: boolean, isRestricted?: (id: string | number) => boolean) => ILogger<Message>;

declare const mergeLogs: (limit: number) => (...logs: ILogItem[][]) => string[];

export { type ILogItem, type ILogger, type IMessage, type IMessageMeta, createLogger, mergeLogs };
